4	unsafe fn test_path_open_read_write(dir_fd: wasi::Fd) {
5	    create_file(dir_fd, "file");
6	
7	    let f_readonly = wasi::path_open(dir_fd, 0, "file", 0, wasi::RIGHTS_FD_READ, 0, 0)
8	        .expect("open file readonly");
9	
10	    let stat = wasi::fd_fdstat_get(f_readonly).expect("get fdstat readonly");
11	    assert!(
12	        stat.fs_rights_base & wasi::RIGHTS_FD_READ == wasi::RIGHTS_FD_READ,
13	        "readonly has read right"
14	    );
15	    assert!(
16	        stat.fs_rights_base & wasi::RIGHTS_FD_WRITE == 0,
17	        "readonly does not have write right"
18	    );
19	
20	    let buffer = &mut [0u8; 100];
21	    let iovec = wasi::Iovec {
22	        buf: buffer.as_mut_ptr(),
23	        buf_len: buffer.len(),
24	    };
25	    let nread = wasi::fd_read(f_readonly, &[iovec]).expect("reading readonly file");
26	    assert_eq!(nread, 0, "readonly file is empty");
27	
28	    let write_buffer = &[1u8; 50];
29	    let ciovec = wasi::Ciovec {
30	        buf: write_buffer.as_ptr(),
31	        buf_len: write_buffer.len(),
32	    };
33	    // PERM is only the failure on windows under wasmtime-wasi. wasi-common
34	    // fails on windows with BADF, so we can't use the `windows =>` syntax
35	    // because that doesn't support alternatives like the agnostic syntax does.
36	    assert_errno!(
37	        wasi::fd_write(f_readonly, &[ciovec])
38	            .err()
39	            .expect("read of writeonly fails"),
40	        wasi::ERRNO_PERM,
41	        wasi::ERRNO_BADF
42	    );
43	
44	    wasi::fd_close(f_readonly).expect("close readonly");
45	
46	    // =============== WRITE ONLY ==================
47	    let f_writeonly = wasi::path_open(dir_fd, 0, "file", 0, wasi::RIGHTS_FD_WRITE, 0, 0)
48	        .expect("open file writeonly");
49	
50	    let stat = wasi::fd_fdstat_get(f_writeonly).expect("get fdstat writeonly");
51	    assert!(
52	        stat.fs_rights_base & wasi::RIGHTS_FD_READ == 0,
53	        "writeonly does not have read right"
54	    );
55	    assert!(
56	        stat.fs_rights_base & wasi::RIGHTS_FD_READDIR == 0,
57	        "writeonly does not have readdir right"
58	    );
59	    assert!(
60	        stat.fs_rights_base & wasi::RIGHTS_FD_WRITE == wasi::RIGHTS_FD_WRITE,
61	        "writeonly has write right"
62	    );
63	
64	    // See above for description of PERM
65	    assert_errno!(
66	        wasi::fd_read(f_writeonly, &[iovec])
67	            .err()
68	            .expect("read of writeonly fails"),
69	        wasi::ERRNO_PERM,
70	        wasi::ERRNO_BADF
71	    );
72	    let bytes_written = wasi::fd_write(f_writeonly, &[ciovec]).expect("write to writeonly");
73	    assert_eq!(bytes_written, write_buffer.len());
74	
75	    wasi::fd_close(f_writeonly).expect("close writeonly");
76	
77	    // ============== READ WRITE =======================
78	
79	    let f_readwrite = wasi::path_open(
80	        dir_fd,
81	        0,
82	        "file",
83	        0,
84	        wasi::RIGHTS_FD_READ | wasi::RIGHTS_FD_WRITE,
85	        0,
86	        0,
87	    )
88	    .expect("open file readwrite");
89	    let stat = wasi::fd_fdstat_get(f_readwrite).expect("get fdstat readwrite");
90	    assert!(
91	        stat.fs_rights_base & wasi::RIGHTS_FD_READ == wasi::RIGHTS_FD_READ,
92	        "readwrite has read right"
93	    );
94	    assert!(
95	        stat.fs_rights_base & wasi::RIGHTS_FD_WRITE == wasi::RIGHTS_FD_WRITE,
96	        "readwrite has write right"
97	    );
98	
99	    let nread = wasi::fd_read(f_readwrite, &[iovec]).expect("reading readwrite file");
100	    assert_eq!(
101	        nread,
102	        write_buffer.len(),
103	        "readwrite file contains contents from writeonly open"
104	    );
105	
106	    let write_buffer_2 = &[2u8; 25];
107	    let ciovec = wasi::Ciovec {
108	        buf: write_buffer_2.as_ptr(),
109	        buf_len: write_buffer_2.len(),
110	    };
111	    let bytes_written = wasi::fd_write(f_readwrite, &[ciovec]).expect("write to readwrite");
112	    assert_eq!(bytes_written, write_buffer_2.len());
113	
114	    let filestat = wasi::fd_filestat_get(f_readwrite).expect("get filestat readwrite");
115	    assert_eq!(
116	        filestat.size as usize,
117	        write_buffer.len() + write_buffer_2.len(),
118	        "total written is both write buffers"
119	    );
120	
121	    wasi::fd_close(f_readwrite).expect("close readwrite");
122	
123	    wasi::path_unlink_file(dir_fd, "file").expect("removing a file");
124	}
