use test_programs::preview1::{assert_errno, open_scratch_directory};

const FILENAME: &str = "test.txt";
const EXPECTED: &[u8] = b"truncation test file\n";

unsafe fn read_contents(dir_fd: wasi::Fd) -> Vec<u8> {
    let file_fd = wasi::path_open(dir_fd, 0, FILENAME, 0, wasi::RIGHTS_FD_READ, 0, 0)
        .expect("opening the file for reading");

    let mut contents = Vec::new();
    let buffer = &mut [0u8; 128];
    loop {
        let nread = wasi::fd_read(
            file_fd,
            &[wasi::Iovec {
                buf: buffer.as_mut_ptr(),
                buf_len: buffer.len(),
            }],
        )
        .expect("reading file content");
        if nread == 0 {
            break;
        }
        contents.extend_from_slice(&buffer[..nread]);
    }

    wasi::fd_close(file_fd).expect("closing the file");
    contents
}

unsafe fn test_file_truncation_readonly(dir_fd: wasi::Fd) {
    // The file should have its initial contents before any truncation attempt.
    assert_eq!(
        read_contents(dir_fd),
        EXPECTED,
        "file contents before attempted truncation"
    );

    // Attempt to open the file with the truncation flag but only read rights.
    // This must be rejected because truncation implies a write operation, and
    // the file was preopened with read permissions only.
    assert_errno!(
        wasi::path_open(
            dir_fd,
            0,
            FILENAME,
            wasi::OFLAGS_TRUNC,
            wasi::RIGHTS_FD_READ,
            0,
            0,
        )
        .err()
        .expect("truncating a read-only file must fail"),
        wasi::ERRNO_PERM
    );

    // The file contents must be unchanged: no truncation occurred.
    assert_eq!(
        read_contents(dir_fd),
        EXPECTED,
        "file contents after attempted truncation"
    );
}

fn main() {
    let mut args = env::args();
    let prog = args.next().unwrap();
    let arg = if let Some(arg) = args.next() {
        arg
    } else {
        eprintln!("usage: {} <scratch directory>", prog);
        process::exit(1);
    };

    // Open scratch directory
    let dir_fd = match open_scratch_directory(&arg) {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{}", err);
            process::exit(1)
        }
    };

    // Run the tests.
    unsafe { test_file_truncation_readonly(dir_fd) }
}
