164	// Compile a component, return the path of the binary:
165	fn compile_component(wasm: &Path, adapter: &[u8]) -> PathBuf {
166	    println!("creating a component from {wasm:?}");
167	    let module = fs::read(wasm).expect("read wasm module");
168	    let component = ComponentEncoder::default()
169	        .module(module.as_slice())
170	        .unwrap()
171	        .validate(true)
172	        .adapter("wasi_snapshot_preview1", adapter)
173	        .unwrap()
174	        .encode()
175	        .expect("module can be translated to a component");
176	    let out_dir = wasm.parent().unwrap();
177	    let stem = wasm.file_stem().unwrap().to_str().unwrap();
178	    let component_path = out_dir.join(format!("{stem}.component.wasm"));
179	    fs::write(&component_path, component).expect("write component to disk");
180	    component_path
181	}
